import {content,interests} from './content.js';
import {esc,csv,download,questionResult,countAnswers,normalizeAnswers} from './core.js';
import {configured,login,logout,rpc} from './api.js';
const root=document.querySelector('main');let sessions=[],selected=null,participants=[],demo=false,poll,detail=null;
const ids=[...content.questions,...content.challenges,...content.situations];
function message(e){const n=document.querySelector('#error');if(n){n.textContent=e.message||e;n.className='error';}}
function signIn(){clearInterval(poll);root.innerHTML=`<div class="narrow"><p class="eyebrow">Espace animateur</p><h1>Retrouver les résultats du groupe</h1><form class="card" id="login"><h2>Connexion</h2>${!configured()?'<div class="notice">La collecte centrale n’est pas encore configurée. La démonstration utilise uniquement des données fictives.</div>':''}<label for="email">Adresse e-mail</label><input id="email" type="email" autocomplete="username" required><label for="password">Mot de passe</label><input id="password" type="password" autocomplete="current-password" required><p id="error" role="alert"></p><div class="actions"><button ${!configured()?'disabled':''}>Se connecter</button><button type="button" class="secondary" id="demo">Voir une séance fictive</button></div></form></div>`;
 document.querySelector('#login').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await login(document.querySelector('#email').value,document.querySelector('#password').value);await rpc('trainer_check',{},true);demo=false;await loadSessions();}catch(err){message(err);e.submitter.disabled=false;}};
 document.querySelector('#demo').onclick=()=>{demo=true;sessions=[{id:'demo',title:'Découverte du numérique',code:'DEMO2026',is_open:true}];selected=sessions[0];participants=[{id:'fictif-1',name:'Camille (fictif)',answers:{Q1:'B',Q2:'NSP',Q3:'A',D1:'Réalisé seul',D2:'Réalisé avec aide',interests:['Fichiers et photos','E-mails et pièces jointes']},observations:{D1:'3',D2:'2'},finished:false,updated_at:new Date().toISOString()},{id:'fictif-2',name:'Alex (fictif)',answers:{Q1:'B',Q2:'D',Q3:'A',Q4:'C',Q5:'B',Q6:'D',Q7:'A',Q8:'C',Q9:'B',Q10:'D',Q11:'A',Q12:'C',D1:'Réalisé seul',D2:'Réalisé seul',D3:'Réalisé avec aide',interests:['Sécurité des comptes'],goal:'Retrouver mes documents'},observations:{},finished:true,updated_at:new Date().toISOString()}];dashboard();};
}
async function loadSessions(){sessions=await rpc('trainer_sessions',{},true);selected=sessions.find(s=>s.id===selected?.id)||sessions[0]||null;await loadParticipants();dashboard();clearInterval(poll);poll=setInterval(async()=>{if(detail||!selected)return;try{await loadParticipants();renderResults();document.querySelector('#freshness').textContent='Actualisé à '+new Date().toLocaleTimeString('fr-FR');}catch(e){message(e);}},15000);}
async function loadParticipants(){participants=selected?(await rpc('trainer_participants',{p_session:selected.id},true)).map(p=>({...p,answers:normalizeAnswers(p.answers)})):[];}
function dashboard(){detail=null;root.innerHTML=`<div class="split"><div><p class="eyebrow">${demo?'Données fictives · aucune transmission':'Espace animateur'}</p><h1>Vos séances</h1></div><button id="logout" class="secondary">${demo?'Quitter la démonstration':'Se déconnecter'}</button></div><p id="error" role="alert"></p><div class="card"><div class="form-row"><div><label for="session">Séance</label><select id="session">${sessions.length?sessions.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?.id?'selected':''}>${esc(s.title)}${s.is_open?'':' · fermée'}</option>`).join(''):'<option>Aucune séance</option>'}</select></div><form id="create"><label for="title">Nouvelle séance</label><div class="actions" style="margin-top:0"><input id="title" maxlength="100" placeholder="Ex. Groupe du mardi" required><button ${demo?'disabled':''}>Créer la séance</button></div></form></div>${selected?`<div class="split"><div><p class="muted">Code à communiquer aux participants</p><strong class="code">${esc(selected.code)}</strong></div><div class="actions"><button id="toggle" class="secondary" ${demo?'disabled':''}>${selected.is_open?'Fermer la collecte':'Rouvrir la collecte'}</button><button id="refresh" class="secondary">Actualiser</button></div></div>`:''}</div><div id="results"></div>`;
 document.querySelector('#logout').onclick=async()=>{if(!demo)await logout().catch(()=>{});demo=false;selected=null;participants=[];signIn();};
 document.querySelector('#create').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const s=await rpc('create_session',{p_title:document.querySelector('#title').value.trim()},true);selected=s;await loadSessions();}catch(err){message(err);e.submitter.disabled=false;}};
 document.querySelector('#session').onchange=async e=>{selected=sessions.find(s=>s.id===e.target.value);try{if(!demo)await loadParticipants();dashboard();}catch(err){message(err);}};
 document.querySelector('#toggle')?.addEventListener('click',async()=>{if(selected.is_open&&!confirm('Fermer la collecte ? Les réponses encore sur les postes ne pourront plus être transmises avant réouverture.'))return;try{await rpc('set_session_open',{p_session:selected.id,p_open:!selected.is_open},true);await loadSessions();}catch(e){message(e);}});
 document.querySelector('#refresh')?.addEventListener('click',async()=>{try{if(!demo)await loadParticipants();renderResults();}catch(e){message(e);}});renderResults();}
function renderResults(){const box=document.querySelector('#results');if(!box)return;if(!selected){box.innerHTML='<div class="card"><h2>Votre première séance</h2><p>Créez une séance pour obtenir un code et accueillir les participants.</p></div>';return;}
 const totals=interests.map(t=>[t,participants.filter(p=>p.answers.interests?.includes(t)).length]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);
 box.innerHTML=`<div class="metrics"><div class="metric"><span>Participants</span><strong>${participants.length}</strong></div><div class="metric"><span>Parcours terminés</span><strong>${participants.filter(p=>p.finished).length}</strong></div><div class="metric"><span>Parcours en cours</span><strong>${participants.filter(p=>!p.finished).length}</strong></div></div><div class="card"><div class="split"><h2>Résultats reçus</h2><div class="actions"><button class="small" id="csv">Exporter le CSV</button><button class="small secondary" id="json">Sauvegarde complète</button></div></div><p class="muted" id="freshness">${demo?'Exemple de séance.':'Les données se mettent à jour toutes les 15 secondes.'}</p>${participants.length?`<div class="scroll"><table><thead><tr><th>Participant</th><th>Réponses*</th><th>État</th><th>Dernière réception</th><th>Détail</th></tr></thead><tbody>${participants.map(p=>`<tr><td>${esc(p.name)}</td><td>${countAnswers(p.answers,ids)} / ${ids.length}</td><td>${p.finished?'Terminé':'En cours'}</td><td>${new Date(p.updated_at).toLocaleTimeString('fr-FR')}</td><td><button class="small secondary" data-id="${esc(p.id)}">Ouvrir</button></td></tr>`).join('')}</tbody></table></div><p class="muted">* Questions, défis et situations renseignés. Ce nombre ne mesure pas la réussite.</p>`:'<p>Les participants apparaîtront ici après avoir rejoint la séance.</p>'}</div><div class="card"><h2>Les sujets demandés</h2>${totals.length?`<ul>${totals.map(([t,n])=>`<li>${esc(t)} : ${n} personne${n>1?'s':''}</li>`).join('')}</ul>`:'<p>Les priorités apparaîtront lorsque les participants rempliront leur bilan.</p>'}<p class="muted">Croisez les demandes avec vos observations avant de choisir les ateliers.</p></div><div class="card"><h2>Connaissances à consolider</h2><div class="scroll"><table><thead><tr><th>Question</th><th>Juste</th><th>Erreur</th><th>Ne sait pas</th><th>Sans réponse</th></tr></thead><tbody>${content.questions.map(q=>`<tr><td>${q.id} · ${esc(q.theme)}</td>${['J','E','NSP','NR'].map(v=>`<td>${participants.filter(p=>questionResult(q,p.answers[q.id])===v).length}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
 document.querySelector('#csv').onclick=exportCSV;document.querySelector('#json').onclick=()=>download('seance-'+selected.code+'.json',JSON.stringify({session:selected,participants},null,2),'application/json');document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>participant(b.dataset.id));}
function participant(id){detail=participants.find(p=>p.id===id);const p=detail;root.innerHTML=`<button id="back" class="secondary">Retour à la séance</button><p class="eyebrow">${esc(selected.title)}</p><h1>${esc(p.name)}</h1><p id="error" role="alert"></p><div class="card"><h2>Connaissances</h2><div class="scroll"><table><thead><tr><th>Question</th><th>Réponse reçue</th><th>Résultat</th></tr></thead><tbody>${content.questions.map(q=>`<tr><td>${q.id} · ${esc(q.q)}</td><td>${esc(q.options['ABCD'.indexOf(p.answers[q.id])]??p.answers[q.id]??'Sans réponse')}</td><td>${questionResult(q,p.answers[q.id])}</td></tr>`).join('')}</tbody></table></div><p>J : juste · E : erreur · NSP : ne sait pas · NR : sans réponse</p></div><form id="observations" class="card"><h2>Vos observations des manipulations</h2><p>3 : sans aide · 2 : aide ponctuelle · 1 : guidage complet · 0 : non réalisé malgré l’aide · NO : non observé</p><div class="scroll"><table><thead><tr><th>Défi</th><th>Déclaration du participant</th><th>Votre observation</th></tr></thead><tbody>${content.challenges.map(c=>`<tr><td>${c.id} · ${esc(c.title)}<details><summary>Critère attendu</summary>${esc(c.success)}</details></td><td>${esc(p.answers[c.id]??'Sans réponse')}<p>${esc(p.answers[c.id+'_note']??'')}</p></td><td><select name="${c.id}">${['NO','0','1','2','3'].map(v=>`<option ${v===(p.observations?.[c.id]??'NO')?'selected':''}>${v}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><label for="note">Votre note</label><textarea id="note" name="note" maxlength="4000">${esc(p.observations?.note??'')}</textarea><button>Enregistrer les observations</button><p id="obs-status" role="status"></p></form><div class="card"><h2>Situations et besoins</h2>${content.situations.map(s=>`<h3>${s.id} · ${esc(s.title)}</h3><p>${esc(p.answers[s.id]||'Sans réponse écrite')}</p><details><summary>Repères de correction</summary>${esc(s.expected)}</details>`).join('')}<h3>Habitudes et priorités</h3>${Object.entries(p.answers).filter(([k])=>!ids.some(i=>i.id===k)&&!k.startsWith('_')&&!/^D\d_note$/.test(k)).map(([k,v])=>`<p><strong>${esc(({devices:'Appareils',internet:'Internet à domicile',already:'Déjà autonome',help:'Besoin d’aide',interests:'Sujets demandés',other_interest:'Autre sujet',success:'Réussite',goal:'Objectif',D4_commune:'Commune',D4_horaire:'Horaire',D4_source:'Source'})[k]||k)}</strong><br>${esc(Array.isArray(v)?v.join(', '):v)}</p>`).join('')}</div>`;
 document.querySelector('#back').onclick=dashboard;document.querySelector('#observations').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const observations=Object.fromEntries(new FormData(e.target));try{if(!demo)await rpc('save_observations',{p_participant:id,p_observations:observations},true);p.observations=observations;document.querySelector('#obs-status').textContent=demo?'Modifié pour la démonstration uniquement.':'Observations enregistrées.';}catch(err){message(err);}finally{e.submitter.disabled=false;}};window.scrollTo(0,0);}
function exportCSV(){const header=['seance','participant_id','prenom','termine','derniere_reception',...content.questions.flatMap(q=>[q.id+'_reponse',q.id+'_resultat']),...content.challenges.flatMap(c=>[c.id+'_declaration',c.id+'_observation',c.id+'_remarque']),...content.situations.map(s=>s.id), 'appareils','internet','deja_autonome','besoin_aide','sujets','autre_sujet','reussite','objectif','observation_generale'];const rows=participants.map(p=>[selected.code,p.id,p.name,p.finished?'oui':'non',p.updated_at,...content.questions.flatMap(q=>[p.answers[q.id]??'',questionResult(q,p.answers[q.id])]),...content.challenges.flatMap(c=>[p.answers[c.id]??'',p.observations?.[c.id]??'NO',p.answers[c.id+'_note']??'']),...content.situations.map(s=>p.answers[s.id]??''),(p.answers.devices||[]).join(' / '),p.answers.internet,p.answers.already,p.answers.help,(p.answers.interests||[]).join(' / '),p.answers.other_interest,p.answers.success,p.answers.goal,p.observations?.note]);download('diagnostic-'+selected.code+'.csv',csv([header,...rows]),'text/csv;charset=utf-8');}
signIn();
